import { useMemo, useState } from 'react';
import {
  Badge,
  Pagination,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
  Text,
} from '@jinx-ui/react';

const PAGE_SIZE = 10;

export type UserStatus = 'active' | 'disabled';

export interface User {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

export interface UsersTableProps {
  users: User[];
}

function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const visibleUsers = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage],
  );

  return (
    <Stack direction="column" gap="var(--jx-space-4)">
      <Table>
        <TableHead>
          <TableRow>
            <TableHeaderCell>Имя</TableHeaderCell>
            <TableHeaderCell>Роль</TableHeaderCell>
            <TableHeaderCell>Статус</TableHeaderCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {visibleUsers.length === 0 ? (
            <TableRow>
              <TableCell colSpan={3}>
                <Text tone="muted">Пользователей нет</Text>
              </TableCell>
            </TableRow>
          ) : (
            visibleUsers.map((user) => (
              <TableRow key={user.id}>
                <TableCell>{user.name}</TableCell>
                <TableCell>{user.role}</TableCell>
                <TableCell>
                  <Badge tone={user.status === 'active' ? 'success' : 'neutral'}>
                    {user.status === 'active' ? 'Активен' : 'Отключён'}
                  </Badge>
                </TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>

      <Pagination page={currentPage} pageCount={pageCount} onChange={setPage} />
    </Stack>
  );
}

export default UsersTable;

